window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-4e12f5e9d4c0bbdc"]={"versions": [{"id": "FIG-4e12f5e9d4c0bbdc", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zweigeteiltes Architektur- und Metamodell-Diagramm im Kontext des AUTOSAR System Templates (TPS System Template, Kapitel „Fan-out / RTE fan-out“). Die linke Seite stellt das Laufzeit- und Schichtenmodell (Software-Architektur) dar, bestehend aus RTE, COM und PduR. Die rechte Seite zeigt das korrespondierende System-Template-Metamodell als Instanzstruktur mit den Entitäten SystemSignal, ISignal und ISignalToPDUMapping. Zweck des Schaubilds ist die Spezifikation eines 1:n-Signal-Fan-outs auf Ebene der RTE, bei dem ein einzelnes logisches Signal in mehrere I-PDUs repliziert wird.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Linke Seite (Laufzeit-/BSW-Schichten und Datenfluss):</p>\n<ul class=\"fig-list\"><li>Oberer eingehender Pfeil: Sendeanforderung aus der Applikationsschicht (SW-C) an die RTE.\n</li><li><code>RTE</code>: Verteilerknoten, der das eingehende Signal in zwei separate Signalpfade aufspaltet.\n</li><li><code>ISignal_S1</code>, <code>ISignal_S2</code>: Ausgehende Signal-Schnittstellen der RTE zur Kommunikationsschicht COM.\n</li><li><code>COM</code>: Schicht zur Verpackung der Signale in I-PDUs.\n</li><li><code>Pdu1</code>, <code>Pdu2</code>: Von COM an den PDU Router übergebene I-PDUs.\n</li><li><code>PduR</code>: PDU-Router-Schicht zur Weiterleitung der I-PDUs an Schnittstellentreiber.\n</li></ul>\n<p class=\"fig-p\">Rechte Seite (Metamodell-Instanzen und Referenzen):</p>\n<ul class=\"fig-list\"><li><code>SystemSignal S</code>: Logisches Gesamtsystem-Signal der Kommunikationsmatrix.\n</li><li><code>ISignal ISignal_S1</code>, <code>ISignal ISignal_S2</code>: Zwei eigenständige ISignal-Instanzen, die beide über Referenzbeziehungen auf dasselbe <code>SystemSignal S</code> verweisen (1:n-Zuordnung).\n</li><li><code>ISignalToPDUMapping S1ToPdu1</code>, <code>ISignalToPDUMapping S2ToPdu2</code>: Mapping-Entitäten, die jeweils auf ihr zugehöriges ISignal (<code>ISignal_S1</code> bzw. <code>ISignal_S2</code>) verweisen und dessen Positionierung in <code>Pdu1</code> bzw. <code>Pdu2</code> definieren.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eine Software-Komponente initiiert das Senden eines Signalwerts über eine RTE-Schnittstelle (z. B. <code>Rte_Write</code>).\n</li><li>Die RTE führt den Signal-Fan-out aus, indem sie die Daten dupliziert und zwei separate Sendeaufrufe an das COM-Modul ausführt – jeweils für <code>ISignal_S1</code> und <code>ISignal_S2</code>.\n</li><li>Das COM-Modul packt <code>ISignal_S1</code> gemäß Mapping <code>S1ToPdu1</code> in die PDU <code>Pdu1</code> und <code>ISignal_S2</code> gemäß Mapping <code>S2ToPdu2</code> in die PDU <code>Pdu2</code>.\n</li><li>COM triggert die Weitergabe beider I-PDUs (<code>Pdu1</code>, <code>Pdu2</code>) an den PDU Router (<code>PduR</code>) zur Übertragung auf dem Kommunikationsnetzwerk.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ definiert das Schaubild die semantische Modellierung des RTE-Signal-Fan-outs im System Template: Mehrere <code>ISignal</code>-Instanzen in unterschiedlichen <code>ISignalIPdu</code>s referenzieren dasselbe <code>SystemSignal</code>. Entwickler- und Generator-Hinweise:</p>\n<ul class=\"fig-list\"><li>Abgrenzung: Zu unterscheiden vom COM Signal Gateway Fan-out (bei dem Quell- und Ziel-Signaltriggerings dasselbe <code>ISignal</code> referenzieren) sowie vom PduR Fan-out (bei dem dieselbe PDU ohne Entpacken vervielfältigt wird).\n</li><li>RTE-Code-Generierung: Der RTE-Generator muss für den betreffenden Sendeport Funktionsaufrufe für beide COM-Signale generieren (z. B. <code>Com_SendSignal</code> für beide ISignals).\n</li><li>Konfiguration COM: Beide Signale (<code>ISignal_S1</code>, <code>ISignal_S2</code>) besitzen im COM-Stack eigenständige Konfigurationen hinsichtlich Update-Bits, Filterung, Übertragungseigenschaften und PDU-Payload-Positionierung.\n</li></ul>"}, {"id": "FIG-9f0a4248bdfbca31", "releases": ["R4.1.3", "R4.2.2", "R4.3.1", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zweigeteiltes Architektur- und Metamodell-Diagramm im Kontext des AUTOSAR System Templates (TPS System Template, Kapitel „Fan-out / RTE fan-out“). Die linke Seite stellt das Laufzeit- und Schichtenmodell (Software-Architektur) dar, bestehend aus RTE, COM und PduR. Die rechte Seite zeigt das korrespondierende System-Template-Metamodell als Instanzstruktur mit den Entitäten SystemSignal, ISignal und ISignalToPDUMapping. Zweck des Schaubilds ist die Spezifikation eines 1:n-Signal-Fan-outs auf Ebene der RTE, bei dem ein einzelnes logisches Signal in mehrere I-PDUs repliziert wird.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Linke Seite (Laufzeit-/BSW-Schichten und Datenfluss):</p>\n<ul class=\"fig-list\"><li>Oberer eingehender Pfeil: Sendeanforderung aus der Applikationsschicht (SW-C) an die RTE.\n</li><li><code>RTE</code>: Verteilerknoten, der das eingehende Signal in zwei separate Signalpfade aufspaltet.\n</li><li><code>ISignal_S1</code>, <code>ISignal_S2</code>: Ausgehende Signal-Schnittstellen der RTE zur Kommunikationsschicht COM.\n</li><li><code>COM</code>: Schicht zur Verpackung der Signale in I-PDUs.\n</li><li><code>Pdu1</code>, <code>Pdu2</code>: Von COM an den PDU Router übergebene I-PDUs.\n</li><li><code>PduR</code>: PDU-Router-Schicht zur Weiterleitung der I-PDUs an Schnittstellentreiber.\n</li></ul>\n<p class=\"fig-p\">Rechte Seite (Metamodell-Instanzen und Referenzen):</p>\n<ul class=\"fig-list\"><li><code>SystemSignal S</code>: Logisches Gesamtsystem-Signal der Kommunikationsmatrix.\n</li><li><code>ISignal ISignal_S1</code>, <code>ISignal ISignal_S2</code>: Zwei eigenständige ISignal-Instanzen, die beide über Referenzbeziehungen auf dasselbe <code>SystemSignal S</code> verweisen (1:n-Zuordnung).\n</li><li><code>ISignalToPDUMapping S1ToPdu1</code>, <code>ISignalToPDUMapping S2ToPdu2</code>: Mapping-Entitäten, die jeweils auf ihr zugehöriges ISignal (<code>ISignal_S1</code> bzw. <code>ISignal_S2</code>) verweisen und dessen Positionierung in <code>Pdu1</code> bzw. <code>Pdu2</code> definieren.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eine Software-Komponente initiiert das Senden eines Signalwerts über eine RTE-Schnittstelle (z. B. <code>Rte_Write</code>).\n</li><li>Die RTE führt den Signal-Fan-out aus, indem sie die Daten dupliziert und zwei separate Sendeaufrufe an das COM-Modul ausführt – jeweils für <code>ISignal_S1</code> und <code>ISignal_S2</code>.\n</li><li>Das COM-Modul packt <code>ISignal_S1</code> gemäß Mapping <code>S1ToPdu1</code> in die PDU <code>Pdu1</code> und <code>ISignal_S2</code> gemäß Mapping <code>S2ToPdu2</code> in die PDU <code>Pdu2</code>.\n</li><li>COM triggert die Weitergabe beider I-PDUs (<code>Pdu1</code>, <code>Pdu2</code>) an den PDU Router (<code>PduR</code>) zur Übertragung auf dem Kommunikationsnetzwerk.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ definiert das Schaubild die semantische Modellierung des RTE-Signal-Fan-outs im System Template: Mehrere <code>ISignal</code>-Instanzen in unterschiedlichen <code>ISignalIPdu</code>s referenzieren dasselbe <code>SystemSignal</code>. Entwickler- und Generator-Hinweise:</p>\n<ul class=\"fig-list\"><li>Abgrenzung: Zu unterscheiden vom COM Signal Gateway Fan-out (bei dem Quell- und Ziel-Signaltriggerings dasselbe <code>ISignal</code> referenzieren) sowie vom PduR Fan-out (bei dem dieselbe PDU ohne Entpacken vervielfältigt wird).\n</li><li>RTE-Code-Generierung: Der RTE-Generator muss für den betreffenden Sendeport Funktionsaufrufe für beide COM-Signale generieren (z. B. <code>Com_SendSignal</code> für beide ISignals).\n</li><li>Konfiguration COM: Beide Signale (<code>ISignal_S1</code>, <code>ISignal_S2</code>) besitzen im COM-Stack eigenständige Konfigurationen hinsichtlich Update-Bits, Filterung, Übertragungseigenschaften und PDU-Payload-Positionierung.\n</li></ul>"}, {"id": "FIG-6248d2e7e3ad7355", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zweigeteiltes Architektur- und Metamodell-Diagramm im Kontext des AUTOSAR System Templates (TPS System Template, Kapitel „Fan-out / RTE fan-out“). Die linke Seite stellt das Laufzeit- und Schichtenmodell (Software-Architektur) dar, bestehend aus RTE, COM und PduR. Die rechte Seite zeigt das korrespondierende System-Template-Metamodell als Instanzstruktur mit den Entitäten SystemSignal, ISignal und ISignalToPDUMapping. Zweck des Schaubilds ist die Spezifikation eines 1:n-Signal-Fan-outs auf Ebene der RTE, bei dem ein einzelnes logisches Signal in mehrere I-PDUs repliziert wird.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Linke Seite (Laufzeit-/BSW-Schichten und Datenfluss):</p>\n<ul class=\"fig-list\"><li>Oberer eingehender Pfeil: Sendeanforderung aus der Applikationsschicht (SW-C) an die RTE.\n</li><li><code>RTE</code>: Verteilerknoten, der das eingehende Signal in zwei separate Signalpfade aufspaltet.\n</li><li><code>ISignal_S1</code>, <code>ISignal_S2</code>: Ausgehende Signal-Schnittstellen der RTE zur Kommunikationsschicht COM.\n</li><li><code>COM</code>: Schicht zur Verpackung der Signale in I-PDUs.\n</li><li><code>Pdu1</code>, <code>Pdu2</code>: Von COM an den PDU Router übergebene I-PDUs.\n</li><li><code>PduR</code>: PDU-Router-Schicht zur Weiterleitung der I-PDUs an Schnittstellentreiber.\n</li></ul>\n<p class=\"fig-p\">Rechte Seite (Metamodell-Instanzen und Referenzen):</p>\n<ul class=\"fig-list\"><li><code>SystemSignal S</code>: Logisches Gesamtsystem-Signal der Kommunikationsmatrix.\n</li><li><code>ISignal ISignal_S1</code>, <code>ISignal ISignal_S2</code>: Zwei eigenständige ISignal-Instanzen, die beide über Referenzbeziehungen auf dasselbe <code>SystemSignal S</code> verweisen (1:n-Zuordnung).\n</li><li><code>ISignalToPDUMapping S1ToPdu1</code>, <code>ISignalToPDUMapping S2ToPdu2</code>: Mapping-Entitäten, die jeweils auf ihr zugehöriges ISignal (<code>ISignal_S1</code> bzw. <code>ISignal_S2</code>) verweisen und dessen Positionierung in <code>Pdu1</code> bzw. <code>Pdu2</code> definieren.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eine Software-Komponente initiiert das Senden eines Signalwerts über eine RTE-Schnittstelle (z. B. <code>Rte_Write</code>).\n</li><li>Die RTE führt den Signal-Fan-out aus, indem sie die Daten dupliziert und zwei separate Sendeaufrufe an das COM-Modul ausführt – jeweils für <code>ISignal_S1</code> und <code>ISignal_S2</code>.\n</li><li>Das COM-Modul packt <code>ISignal_S1</code> gemäß Mapping <code>S1ToPdu1</code> in die PDU <code>Pdu1</code> und <code>ISignal_S2</code> gemäß Mapping <code>S2ToPdu2</code> in die PDU <code>Pdu2</code>.\n</li><li>COM triggert die Weitergabe beider I-PDUs (<code>Pdu1</code>, <code>Pdu2</code>) an den PDU Router (<code>PduR</code>) zur Übertragung auf dem Kommunikationsnetzwerk.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ definiert das Schaubild die semantische Modellierung des RTE-Signal-Fan-outs im System Template: Mehrere <code>ISignal</code>-Instanzen in unterschiedlichen <code>ISignalIPdu</code>s referenzieren dasselbe <code>SystemSignal</code>. Entwickler- und Generator-Hinweise:</p>\n<ul class=\"fig-list\"><li>Abgrenzung: Zu unterscheiden vom COM Signal Gateway Fan-out (bei dem Quell- und Ziel-Signaltriggerings dasselbe <code>ISignal</code> referenzieren) sowie vom PduR Fan-out (bei dem dieselbe PDU ohne Entpacken vervielfältigt wird).\n</li><li>RTE-Code-Generierung: Der RTE-Generator muss für den betreffenden Sendeport Funktionsaufrufe für beide COM-Signale generieren (z. B. <code>Com_SendSignal</code> für beide ISignals).\n</li><li>Konfiguration COM: Beide Signale (<code>ISignal_S1</code>, <code>ISignal_S2</code>) besitzen im COM-Stack eigenständige Konfigurationen hinsichtlich Update-Bits, Filterung, Übertragungseigenschaften und PDU-Payload-Positionierung.\n</li></ul>"}], "trans": [{"from": "FIG-4e12f5e9d4c0bbdc", "to": "FIG-9f0a4248bdfbca31", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-9f0a4248bdfbca31", "to": "FIG-6248d2e7e3ad7355", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-6248d2e7e3ad7355", "to": "FIG-9f0a4248bdfbca31", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
